package nnue

import _ "embed"

// embeddedNet is the default NNUE network compiled into the binary, so the engine is self-contained
// and needs no external net file. Loaded on demand by Embedded.
//
// pawnstar-v20.bin is the net of release 2.0.0 — the mirrored, eight-output-head shape (this build's
// default), trained entirely on Leela Chess Zero self-play data, and the same blob byte for byte as
// pawnstar and pawnstar-rs ship. Networks up to and including v12 were trained on self-play data
// generated by PlentyChess, by Yoshie2000; that data is no longer used. README.md, "The evaluation
// network", carries the attribution in full.
//
//go:embed pawnstar-v20.bin
var embeddedNet []byte
